export const SESSION_KEYS = ['A', 'B', 'C']


// ── Exercises ────────────────────────────────────────────────────────────────
// cat: warm-up and main-work groups, or 'stretch'. mode: 'time' (seconds) or
// 'reps'. uni: 1 for one-sided moves (done each side). p: per-phase
// prescription override. t: a stretch's hold time in seconds. area: a stretch's
// cool-down area (see AREAS).
const T = 'time', R = 'reps'
const ex = (id, name, eq, cat, mode, uni, cues, extra = {}) => ({ id, name, eq, cat, mode, uni, cues, ...extra })
const st = (id, name, eq, uni, t, area, cues) => ex(id, name, eq, 'stretch', T, uni, cues, { t, area })

