// ── How-to details: setup, numbered steps, what you should feel ───────────────
export const DETAILS = {
  wgs: {"setup":"Clear a mat-length of floor and start standing.","steps":["Step one foot far forward into a long lunge and lower the back knee to the floor.","Place both hands on the floor inside the front foot.","Drop the elbow on the front-foot side toward the instep and hold for a breath.","Put that hand back down, rotate your chest toward the front knee and reach the arm to the ceiling, eyes following your hand.","Return and repeat; switch sides when the timer says."],"feel":"A stretch at the front of the back hip and the inner thigh of the front leg, plus rotation through the middle of your back."},
  openbook: {"setup":"Lie on your side with a cushion under your head, hips and knees bent to 90°, arms straight out in front with palms together.","steps":["Keep your knees pressed together and on the floor throughout.","Lift the top arm and sweep it up and over in an arc, following it with your eyes.","Let the arm fall open toward the floor behind you as far as your upper back allows.","Breathe out, pause, then sweep it back. Repeat slowly, then turn over."],"feel":"Rotation and a gentle opening across the chest and between the shoulder blades, not in the lower back."},
  pullapart: {"setup":"Stand tall holding a light band in both hands, arms straight out in front at shoulder height, hands shoulder-width apart.","steps":["Set your shoulders down away from your ears.","Pull the band apart by moving your hands out to the sides, arms straight.","Finish with the band touching your chest and shoulder blades squeezed together.","Control the band back without letting your shoulders shrug."],"feel":"Work between and behind your shoulder blades and in the back of your shoulders, not in your neck."},
  bridge: {"setup":"Lie on your back, knees bent, feet flat and hip-width apart, heels about a hand's length from your bum. Arms by your sides.","steps":["Gently flatten your lower back by drawing your ribs down.","Push through your heels and lift your hips until your body is straight from knees to shoulders.","Squeeze your glutes hard and hold for 2 seconds.","Lower slowly, touch down and go again."],"feel":"Your glutes doing the work. If it's mostly hamstrings, bring your feet closer; if it's your lower back, don't lift as high."},
  hip9090: {"setup":"Sit on the floor with both knees bent at 90°, feet a bit wider than hip-width, hands on the floor behind you.","steps":["Let both knees fall to one side so the front shin crosses in front of you and the back leg points out to the side.","Sit up tall through your chest.","Lift both knees and rotate them over to the other side.","Keep switching slowly; take your hands away once it feels easy."],"feel":"Rotation in both hips, with the front hip opening outward and the back hip turning inward. Some stretch in the outer glute."},
  wrists: {"setup":"Kneel on a mat, or stand by a table.","steps":["Clasp your hands and roll your wrists in circles, 10 each way.","On hands and knees, place palms down with fingers pointing back toward your knees and rock back gently.","Turn your hands over so the backs are on the floor, fingers still pointing back, and rock gently again.","Finish by flicking your fingers open and closed quickly for 10 seconds."],"feel":"A stretch through both sides of the forearms and warmth in the hands. Keep it mild; no sharp wrist pain."},
  monster: {"setup":"Put a mini band just above your knees (easier) or around your ankles (harder). Feet hip-width apart.","steps":["Drop into a half squat, chest up, toes forward.","Step sideways with the lead foot, keeping tension on the band.","Follow with the trailing foot without letting your feet come fully together.","Take the set number of steps one way, then come back the other way."],"feel":"A burn on the outside of your hips. Your knees should stay in line with your toes, not cave in."},
  goblet: {"setup":"Hold a kettlebell by the horns, or a dumbbell upright by one end, tight against your chest. Feet slightly wider than shoulder-width, toes turned out a little.","steps":["Breathe in and brace your stomach.","Push your knees out and sit down between your heels, chest up.","Go as low as you can with heels down and back flat, ideally elbows brushing the inside of your knees.","Drive up through your whole foot to stand, breathing out near the top."],"feel":"Work in your quads and glutes, with your upper back holding the weight up. No pinching at the front of the hips."},
  cossack: {"setup":"Stand with feet very wide, toes turned out slightly. Hold a kettlebell at your chest, or hold your arms in front for balance.","steps":["Shift your weight onto one leg and sit down into that hip, bending the knee.","Let the other leg straighten, heel on the floor and toes pointing up.","Go as low as you can with the working heel flat and chest up.","Push back to the middle, then go to the other side."],"feel":"Strength in the bent leg's quad and glute, and a stretch through the inner thigh of the straight leg."},
  bss: {"setup":"Stand about two steps in front of a bench, sofa or chair and rest the top of one foot on it behind you. Hold dumbbells at your sides or a kettlebell at your chest.","steps":["Check your front foot is far enough forward that the knee can bend without the heel lifting.","Lower straight down until your back knee almost touches the floor.","Keep a slight forward lean from the hips.","Push through the front heel to stand. Finish all reps, then switch legs."],"feel":"Mostly the front leg's glute and quad, with a stretch at the front of the back hip. The back leg only balances."},
  revlunge: {"setup":"Stand tall with feet hip-width apart, holding dumbbells at your sides, a kettlebell at your chest, or no weight.","steps":["Take a long step backward, landing on the ball of the back foot.","Lower until your back knee is just above the floor and your front shin is roughly vertical.","Keep most of your weight on the front foot.","Push through the front heel to step back up to standing. Do all reps on one side, then switch."],"feel":"Work in the front leg's glute and quad. Your knees should feel comfortable; if not, don't go as deep."},
  latlunge: {"setup":"Stand with feet together, holding a kettlebell or dumbbell at your chest, or no weight.","steps":["Take a big step out to the side, toes pointing forward.","Sit your hips back and down over the stepping foot, bending that knee.","Keep the other leg straight with its foot flat.","Push off the bent leg to return to standing. Do all reps on one side, then switch."],"feel":"The bent leg's glute and quad working, and a stretch along the inner thigh of the straight leg."},
  stepup: {"setup":"Use a sturdy step, box or bench around knee height. Hold dumbbells at your sides, or no weight.","steps":["Place your whole working foot on the step.","Lean slightly forward and drive through that foot to stand up on the step.","Don't push off the bottom foot; let it trail up.","Lower slowly until the bottom foot touches down. Do all reps, then switch."],"feel":"The top leg's glute and quad doing all the lifting. If the calf of the bottom leg is working hard, you're pushing off it."},
  swing: {"setup":"Place the kettlebell about a foot in front of you and stand with feet a bit wider than hip-width.","steps":["Hinge at the hips with a flat back and grab the handle with both hands.","Hike the bell back between your legs like a rugby snap.","Snap your hips forward hard so the bell floats up to about chest height, arms relaxed.","At the top, stand tall with glutes and stomach tight. Let the bell fall and hinge to receive it, straight into the next rep.","After the last rep, hike it back and park it on the floor."],"feel":"Power from your glutes and hamstrings, a firm stomach at the top and a grip workout. Your lower back and shoulders shouldn't be lifting it."},
  rdl: {"setup":"Stand with feet hip-width apart, holding dumbbells or a kettlebell in front of your thighs.","steps":["Soften your knees slightly and keep them at that angle.","Push your hips back as if closing a car door with your bum, sliding the weights down the front of your legs.","Keep your back flat until you feel a strong hamstring stretch, usually around knee height.","Drive your hips forward to stand tall, squeezing your glutes at the top."],"feel":"A deep stretch and work in the hamstrings and glutes. Your lower back holds position but shouldn't ache."},
  slrdl: {"setup":"Stand on one leg holding a dumbbell or kettlebell in the opposite hand. Use a wall for balance with your free hand if needed.","steps":["Soften the standing knee slightly.","Hinge forward at the hip, letting the free leg extend straight behind you.","Keep your hips level, as if both hip bones are headlights shining at the floor.","Lower until you feel a strong hamstring stretch, then drive through the standing heel to return. Do all reps, then switch."],"feel":"Hamstring and glute on the standing leg, with your foot and ankle working to keep you balanced."},
  thrust: {"setup":"Sit on the floor with your upper back, just below the shoulder blades, against the edge of a sofa or bench. Rest a dumbbell or kettlebell on your hips, or pin a band across them with your hands.","steps":["Plant your feet flat and hip-width apart so your shins will be vertical at the top.","Tuck your chin and keep your ribs down.","Drive through your heels to lift your hips until your body is flat from knees to shoulders.","Squeeze your glutes hard for a second, then lower under control."],"feel":"Strong work in the glutes and very little in the lower back. If you feel it in your back, lift less high and keep your ribs down."},
  goodmorning: {"setup":"Stand on a long band with feet hip-width apart and loop the other end behind your neck, across your upper back.","steps":["Soften your knees and brace your stomach.","Hinge forward from the hips with a flat back until your torso is close to parallel with the floor.","Keep the band pulling on your upper back the whole way down.","Squeeze your glutes and drive your hips forward to stand tall."],"feel":"Hamstrings and glutes working, and the muscles along your spine holding steady rather than bending."},
  jumpsquat: {"setup":"Stand with feet shoulder-width apart on a forgiving surface, like a mat or grass.","steps":["Dip quickly into a quarter to half squat, swinging your arms back.","Explode up as high as you can, driving your arms up.","Land softly on the balls of your feet, sinking through hips and knees to absorb it.","Stand, reset for a second and repeat. Quality over speed."],"feel":"Snappy work in your legs and a quiet landing. If landings are loud or your knees cave, jump lower."},
  broadjump: {"setup":"Stand with feet hip-width apart with clear space in front of you.","steps":["Swing your arms back while you hinge your hips and bend your knees.","Swing your arms forward and jump out as far as you can.","Land on both feet, sinking into a squat to absorb it.","Hold the landing for a second, then walk back to reset."],"feel":"Explosive drive from your hips and a controlled, balanced landing."},
  skater: {"setup":"Stand on your right leg with clear space to your left.","steps":["Sink into a quarter squat on the right leg.","Push off sideways and bound onto your left leg.","Land softly and hold for a second, letting the right foot trail behind without touching down.","Bound back to the right. Each hop is one rep."],"feel":"Your outer hip and glute working on each landing, and your ankle and foot stabilising."},
  pushup: {"setup":"Hands on the floor just wider than your shoulders, legs straight behind you. To make it easier, put your hands on a sofa or bench.","steps":["Squeeze your glutes and brace so your body is one straight line from head to heels.","Lower your chest toward the floor with elbows about 45° from your body.","Pause just above the floor.","Push the floor away to return to the top, keeping the straight line."],"feel":"Chest, front of the shoulders and triceps, with your stomach stopping your hips from sagging."},
  floorpress: {"setup":"Lie on your back with knees bent and feet flat, a dumbbell in each hand or a kettlebell held in both, over your chest.","steps":["Lower until the backs of your upper arms touch the floor, elbows about 45° from your body.","Pause briefly without relaxing.","Press back up and slightly in until your arms are straight."],"feel":"Chest and triceps. Your shoulders should feel comfortable because the floor limits how deep you go."},
  hkpress: {"setup":"Kneel on one knee on a cushion, other foot flat in front. Hold a dumbbell or kettlebell at shoulder height on the same side as the down knee.","steps":["Squeeze the glute of the down leg and brace your stomach.","Press the weight straight up until your arm is straight and your bicep is beside your ear.","Don't lean back or to the side.","Lower under control to your shoulder. Do all reps, then switch sides."],"feel":"Shoulder and triceps pressing, with your core and down-leg glute holding you upright."},
  bandpress: {"setup":"Anchor a band behind you at chest height, round a post or in a door anchor. Hold a handle in each hand at your chest, one foot forward.","steps":["Brace your stomach and lean slightly forward.","Press both hands straight out until your arms are straight.","Control the band back until your hands reach your chest."],"feel":"Chest and front of the shoulders, with a smooth pump rather than a strain."},
  row: {"setup":"Put one knee and the same-side hand on a bench or sofa with your back flat. Hold a dumbbell or kettlebell in the other hand, arm hanging straight.","steps":["Brace your stomach and keep your back flat.","Pull the weight toward your hip, driving the elbow back rather than up.","Squeeze your shoulder blade toward your spine at the top and pause.","Lower slowly until your arm is straight. Do all reps, then switch sides."],"feel":"The big muscle down the side of your back (lats) and between your shoulder blades. Your bicep helps but shouldn't lead."},
  bandrow: {"setup":"Anchor a band at chest height in front of you. Hold the ends and step back until it has tension, knees soft.","steps":["Stand tall with shoulders down.","Pull your hands to your lower ribs, driving your elbows back.","Squeeze your shoulder blades together and pause.","Let your arms straighten under control."],"feel":"Mid-back and between the shoulder blades, with no tension in your neck."},
  renegade: {"setup":"Get into a high plank with your hands on two dumbbells, feet wider than hip-width.","steps":["Brace hard so your hips stay square to the floor.","Row one dumbbell to your hip while pushing the other into the floor.","Lower it back down with control.","Alternate sides. Each side counts as one rep."],"feel":"Your back muscles rowing, and your whole trunk fighting to stop your hips twisting."},
  facepull: {"setup":"Anchor a band at face height. Hold the ends with palms facing down and step back until there's tension.","steps":["Stand tall with shoulders down.","Pull the band toward your eyes, elbows high and wide.","At the end, rotate your hands back so your knuckles point behind you, like a double bicep pose.","Hold for a second, then return slowly."],"feel":"Rear shoulders and the muscles between your shoulder blades. Stop if you feel it at the front of the shoulder."},
  highpull: {"setup":"Stand with feet shoulder-width apart, a kettlebell on the floor between your feet or a dumbbell in each hand.","steps":["Hinge down with a flat back and grip the weight.","Drive your hips forward explosively, like jumping without leaving the floor.","As the weight rises, pull your elbows up and out so it reaches about chest height, close to your body.","Lower under control and go again."],"feel":"Power from your hips first, then your upper back and shoulders finishing the pull."},
  deadbug: {"setup":"Lie on your back with arms pointing at the ceiling and knees bent at 90° above your hips.","steps":["Press your lower back into the floor and keep it there.","Slowly lower one arm behind your head and the opposite leg toward the floor, breathing out.","Stop just before your back starts to lift.","Return and switch sides."],"feel":"Deep work in your lower stomach, with your lower back flat and comfortable."},
  pallof: {"setup":"Anchor a band at chest height to your side. Hold it at your chest with both hands and step away until there's tension. Feet shoulder-width, knees soft.","steps":["Brace your stomach.","Press your hands straight out in front of your chest.","Hold for 2 seconds while the band tries to twist you toward the anchor.","Bring your hands back in. Do all reps, then face the other way."],"feel":"Your obliques and deep core working to stop you rotating. Your arms only hold the band."},
  sideplank: {"setup":"Lie on your side with your elbow directly under your shoulder, legs straight and stacked, or knees bent to make it easier.","steps":["Lift your hips so your body is in a straight line from head to feet.","Push the floor away through your elbow.","Hold still and breathe normally.","Lower and switch sides when the timer says."],"feel":"The side of your stomach and the outside of your bottom hip, not your shoulder."},
  hollow: {"setup":"Lie on your back with arms stretched overhead and legs straight.","steps":["Press your lower back into the floor.","Lift your shoulders, arms and legs a few inches off the floor into a shallow banana shape.","Hold with your lower back glued down, breathing steadily.","If your back lifts, bend your knees or bring your arms to your sides."],"feel":"A strong burn through your whole stomach, especially the lower part."},
  birddog: {"setup":"Start on hands and knees, hands under shoulders, knees under hips, back flat.","steps":["Brace your stomach as if about to be poked.","Slowly reach one arm forward and the opposite leg back until both are straight and level with your body.","Hold for 2 seconds without your hips tilting.","Return and switch sides."],"feel":"Glutes and the muscles along your spine working gently, with your core keeping everything still."},
  plankdrag: {"setup":"Get into a high plank with a dumbbell or kettlebell on the floor just outside one hand, feet wide for balance.","steps":["Brace so your hips stay level.","Reach under your body with the opposite hand and drag the weight across to the other side.","Place that hand back down.","Reach with the other hand and drag it back. Each drag is one rep."],"feel":"Your core and shoulders resisting rotation as your weight shifts onto one hand."},
  chop: {"setup":"Anchor a band above head height. Kneel side-on to it on the knee nearest the anchor, holding the band with both hands up by the anchor.","steps":["Brace your stomach and keep your hips facing forward.","Pull the band diagonally down across your body toward your opposite hip.","Let your torso rotate, not just your arms.","Return slowly. Do all reps, then turn around."],"feel":"Your obliques turning and controlling the band, and your glutes holding your hips steady."},
  farmer: {"setup":"Hold the heaviest dumbbells or kettlebells you can grip, one at each side.","steps":["Stand tall with shoulders down and back.","Walk with short, controlled steps, or march on the spot if you're short of room.","Keep your arms straight and stop the weights swinging.","Put the weights down under control at the end."],"feel":"Grip and forearms burning, with your upper back and core holding you upright."},
  suitcase: {"setup":"Hold one heavy dumbbell or kettlebell at your side, other arm free.","steps":["Stand tall with shoulders level.","Walk slowly without leaning toward or away from the weight.","Breathe steadily.","Swap hands when the timer says."],"feel":"The side of your stomach opposite the weight working hard to keep you straight, plus your grip."},
  bottomsup: {"setup":"Hold a kettlebell upside down by the handle so the bell points at the ceiling.","steps":["Squeeze the handle as hard as you can.","Bring it to shoulder height with your elbow at 90° and wrist straight.","Hold it still, balancing the bell.","Switch hands when the timer says. Start light; it's harder than it looks."],"feel":"Intense grip and forearm work, plus your shoulder stabilising."},
  pinch: {"setup":"Stand holding a dumbbell by one of its heads, fingers on one side of the end plate and thumb on the other.","steps":["Lift it so it hangs at your side.","Squeeze with fingers and thumb to stop it slipping.","Stand tall and hold still.","Switch hands when the timer says."],"feel":"Your thumb and fingers working hard, and a burn in your forearm."},
  attack: {"setup":"Hold a dumbbell or kettlebell in each hand, or no weight. Feet between hip- and shoulder-width apart.","steps":["Bend your knees and hinge from the hips until your chest is over imaginary bars.","Keep a flat back and your elbows slightly bent and out, as if gripping the handlebars.","Keep your weight centred with heels heavy.","Hold and breathe. For a challenge, shift your weight forward and back as if riding."],"feel":"Quads, glutes and hamstrings burning while your back and shoulders hold shape, just like the end of a long run."},
  burpee: {"setup":"Stand with clear space around you.","steps":["Squat down and put your hands on the floor.","Jump or step your feet back into a plank and lower your chest to the floor.","Push up and jump or step your feet back toward your hands.","Stand up and do a small jump with your hands overhead."],"feel":"Heart rate climbing fast and your whole body working. Stepping instead of jumping keeps it lower impact."},
  climbers: {"setup":"Start in a high plank with your hands under your shoulders.","steps":["Brace your stomach and keep your hips low.","Drive one knee toward your chest.","Switch legs quickly, as if running on the spot.","Keep your shoulders over your hands throughout."],"feel":"Stomach and shoulders working and your heart rate climbing."},
  hamstrap: {"setup":"Lie on your back with a band, belt or towel looped around the ball of one foot, other leg straight on the floor.","steps":["Hold the ends and straighten the looped leg toward the ceiling.","Gently pull the leg toward you until you feel a stretch, knee straight.","Keep your hips and the other leg flat on the floor.","Relax into it on each breath out. Switch legs when the timer says."],"feel":"A steady stretch along the back of your thigh. If you feel tingling in your calf or foot, ease off a little."},
  seatedham: {"setup":"Sit on the floor with one leg straight and the other foot against the inside of the straight leg's thigh.","steps":["Sit up tall and turn your chest to face the straight leg.","Hinge forward from your hips, keeping your back long.","Reach toward your foot until you feel the stretch.","Breathe slowly and ease further as you relax. Switch sides when the timer says."],"feel":"A stretch along the back of your thigh and behind the knee, not in your lower back."},
  calfwall: {"setup":"Stand facing a wall with your hands on it at shoulder height, one foot stepped back about a metre.","steps":["Keep the back leg straight and its heel pressed into the floor.","Point both feet straight ahead.","Bend your front knee and lean toward the wall until you feel the stretch.","Hold and breathe. Switch legs when the timer says."],"feel":"A stretch in the upper, fleshy part of the back leg's calf."},
  soleus: {"setup":"Stand facing a wall with your hands on it, one foot stepped back about half a metre.","steps":["Bend both knees and sink your weight down.","Keep the back heel pressed into the floor.","Push the back knee forward over the toes until you feel the stretch.","Hold and breathe. Switch legs when the timer says."],"feel":"A stretch low in the calf, close to the Achilles, lower down than the straight-knee version."},
  footroll: {"setup":"Sit or stand with a tennis ball, massage ball or bottle under one foot, bare or in socks.","steps":["Press down with enough weight to feel firm pressure.","Roll slowly from heel to the ball of the foot and back.","Pause on any tender spots for a few breaths.","Switch feet when the timer says."],"feel":"Firm pressure and release through the arch and sole of your foot. Discomfort is fine; sharp pain isn't."},
  toestretch: {"setup":"Kneel on a mat with your toes tucked under and heels pointing up.","steps":["Slowly sit back toward your heels.","Keep your weight on the balls of your feet, toes bent back.","Use your hands on the floor to control how much weight goes through your feet.","Hold and breathe."],"feel":"A strong stretch along the soles of your feet and under your toes. It can be intense at first, so build up."},
  thread: {"setup":"Start on hands and knees, hands under shoulders and knees under hips.","steps":["Lift one arm and slide it under your body, palm up, toward the opposite side.","Lower that shoulder and the side of your head to the floor.","Keep your hips over your knees.","Relax and breathe into your upper back. Switch sides when the timer says."],"feel":"A stretch across the back of the shoulder and rotation between the shoulder blades."},
  doorway: {"setup":"Stand in a doorway with one forearm on the frame, elbow at shoulder height and bent to 90°.","steps":["Step forward through the doorway with the same-side foot.","Turn your chest slightly away from the arm.","Keep your ribs down and your shoulder away from your ear.","Hold and breathe. Switch arms when the timer says."],"feel":"A stretch across the front of your chest and shoulder. Move the elbow a little higher or lower to find the spot."},
  latstretch: {"setup":"Kneel facing a sofa or chair with your elbows on the edge and hands together, palms touching.","steps":["Walk your knees back until your hips are above them.","Sink your chest toward the floor, letting your head drop between your arms.","Bend your hands back toward your upper back to deepen it.","Breathe slowly into your upper back."],"feel":"A stretch down the sides of your back into your armpits, and an opening through your upper back and shoulders."},
  hipflexor: {"setup":"Kneel on a mat or cushion with one foot flat on the floor in front of you in a lunge.","steps":["Tuck your tailbone under so your pelvis tilts back.","Squeeze the glute of the kneeling leg.","Shift your weight forward until you feel a stretch at the front of the back hip.","Reach the arm on that side overhead for a little more. Breathe slowly and switch sides when the timer says."],"feel":"A stretch along the front of the back hip and thigh, not in the lower back or the front knee."},
  figure4: {"setup":"Lie on your back on the floor with both knees bent and feet flat.","steps":["Cross one ankle over the opposite knee, keeping that foot flexed.","Hold behind the thigh of the supporting leg and draw it gently toward your chest.","Let the crossed knee drift away from you.","Keep your head and shoulders relaxed on the floor and switch sides when the timer says."],"feel":"A stretch deep in the buttock and outer hip on the crossed-leg side."},
  child: {"setup":"Kneel on a mat with your knees about hip-width apart and your big toes touching.","steps":["Sit your hips back toward your heels.","Walk your hands forward along the floor and rest your forehead down.","Let your lower back round and soften.","Breathe slowly into your lower back and ribs."],"feel":"A gentle lengthening along the whole of your lower back and the sides of your ribs."},
  lumbartwist: {"setup":"Lie on your back with your arms out to the sides in a T and your knees bent.","steps":["Lift your feet off the floor with your knees stacked over your hips.","Lower both knees together toward the floor on one side.","Keep both shoulders pressed down and turn your head the other way if comfortable.","Breathe out slowly. Bring the knees back to the middle and switch sides when the timer says."],"feel":"A mild twist through the lower back and hip on the side you are turning away from, with no sharp pinching."},
  floorchest: {"setup":"Lie face down on a mat with one arm straight out to the side at shoulder height, palm down.","steps":["Put the other hand on the floor beside your ribs.","Slowly roll your body toward the opposite hip, keeping the outstretched arm on the floor.","Stop when you feel a stretch across the front of the shoulder and chest.","Breathe out and relax. Switch sides when the timer says."],"feel":"A stretch across the front of the chest and shoulder of the outstretched arm."},
  wristflex: {"setup":"Stand or kneel and hold one arm straight out in front with the palm facing up.","steps":["With the other hand, gently draw the fingers and palm back toward the floor.","Keep the elbow straight and the shoulder relaxed.","Hold, breathing slowly.","Switch to the other arm when the timer says."],"feel":"A stretch along the underside of the forearm, from the wrist toward the elbow."},
  wristext: {"setup":"Stand or kneel and hold one arm straight out in front with the palm facing down.","steps":["With the other hand, gently draw the back of the hand and fingers down and in toward you.","Keep the elbow straight and the shoulder relaxed.","Hold, breathing slowly.","Switch to the other arm when the timer says."],"feel":"A stretch along the top of the forearm, from the back of the hand toward the elbow."},
}

