// The reason an exercise matters for a sport: the sport's own line if it has
// one, otherwise the general line.
export const whyFor = (id, sport) => SPORT_WHY[sport]?.[id] ?? WHY[id] ?? ''


// ── Programs ─────────────────────────────────────────────────────────────────
// Per sport, three sessions (A, B, C): a name, three warm-up moves and the main
// work for each phase. The cool-down is not part of a program: it is built from
// the person's chosen areas (see coolDown in engine.js). The mtb program is the
// original; the others are drafted from the same library with the same shape.
const prog = (name, warm, p1, p2, p3) => ({ name, warm, main: { 1: p1, 2: p2, 3: p3 } })

